// Generates supabase/seed/002_bible_seed.sql from src/data/brokerBible.json
// Usage: node scripts/make-seed-sql.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const bible = JSON.parse(readFileSync(new URL('../src/data/brokerBible.json', import.meta.url), 'utf8'));
const lines = [
  '-- Generated by scripts/make-seed-sql.mjs. Run AFTER 001_cloud.sql. Safe to re-run: existing items are kept.',
  'begin;',
];
const TAG = '$json$';
function add(kind, items) {
  for (const item of items) {
    if (!item.id) throw new Error(`${kind} without id`);
    const text = JSON.stringify(item);
    if (text.includes(TAG)) throw new Error(`${kind} ${item.id} contains ${TAG}`);
    lines.push(
      `insert into public.bible_items (kind, id, data, change_note) values ('${kind}', '${item.id}', ${TAG}${text}${TAG}::jsonb, 'Initial import v${bible.meta.version}') on conflict (kind, id) do nothing;`
    );
  }
}
add('sector', bible.sectors);
add('stage', bible.stages);
add('entry', bible.entries);
add('scenario', bible.scenarios);
lines.push('commit;');
writeFileSync(new URL('../supabase/seed/002_bible_seed.sql', import.meta.url), lines.join('\n') + '\n');
console.log(`seed written: ${bible.sectors.length} sectors, ${bible.stages.length} stages, ${bible.entries.length} entries, ${bible.scenarios.length} scenarios`);
